const crypto = require('crypto');
const http = require('http');

// Custom binary session token format:
// [version:1][flags:1][payload_len:1][payload:N][hmac:32]
// payload contains: [user_id:4][role:1][expiry:8][extra_len:1][extra:M]

const SECRET_KEY = crypto.randomBytes(32);
const ADMIN_ROLE = 0x01;
const USER_ROLE = 0x02;

const users = new Map();
users.set(1, { name: 'admin', role: ADMIN_ROLE });
users.set(2, { name: 'user', role: USER_ROLE });

function createToken(userId, role, extra = Buffer.alloc(0)) {
  const expiry = Buffer.alloc(8);
  expiry.writeBigUInt64BE(BigInt(Date.now() + 3600000));

  const payload = Buffer.alloc(4 + 1 + 8 + 1 + extra.length);
  payload.writeUInt32BE(userId, 0);
  payload.writeUInt8(role, 4);
  expiry.copy(payload, 5);
  payload.writeUInt8(extra.length, 13);
  extra.copy(payload, 14);

  const header = Buffer.alloc(3);
  header.writeUInt8(0x01, 0); // version
  header.writeUInt8(0x00, 1); // flags
  header.writeUInt8(payload.length, 2); // payload_len

  const tokenBody = Buffer.concat([header, payload]);
  const hmac = crypto.createHmac('sha256', SECRET_KEY).update(tokenBody).digest();

  return Buffer.concat([tokenBody, hmac]);
}

function parseToken(tokenBuf) {
  if (!Buffer.isBuffer(tokenBuf) || tokenBuf.length < 36) {
    return { valid: false, error: 'Token too short' };
  }

  const version = tokenBuf.readUInt8(0);
  if (version !== 0x01) {
    return { valid: false, error: 'Invalid version' };
  }

  const flags = tokenBuf.readUInt8(1);
  const payloadLen = tokenBuf.readInt8(2); // Read as signed byte

  // Validate payload length
  if (payloadLen < 14) {
    return { valid: false, error: 'Payload too short' };
  }

  // Check total token length matches
  const expectedLen = 3 + payloadLen + 32;
  if (tokenBuf.length !== expectedLen) {
    return { valid: false, error: 'Length mismatch' };
  }

  // Verify HMAC
  const tokenBody = tokenBuf.slice(0, 3 + payloadLen);
  const providedHmac = tokenBuf.slice(3 + payloadLen);
  const expectedHmac = crypto.createHmac('sha256', SECRET_KEY).update(tokenBody).digest();

  if (!crypto.timingSafeEqual(providedHmac, expectedHmac)) {
    return { valid: false, error: 'Invalid signature' };
  }

  // Parse payload
  const payloadStart = 3;
  const userId = tokenBuf.readUInt32BE(payloadStart);
  const role = tokenBuf.readUInt8(payloadStart + 4);
  const expiry = tokenBuf.readBigUInt64BE(payloadStart + 5);
  const extraLen = tokenBuf.readUInt8(payloadStart + 13);

  // Validate expiry
  if (BigInt(Date.now()) > expiry) {
    return { valid: false, error: 'Token expired' };
  }

  // Extract extra data
  const extraData = tokenBuf.slice(payloadStart + 14, payloadStart + 14 + extraLen);

  return {
    valid: true,
    userId,
    role,
    expiry,
    extraData,
    flags
  };
}

function isAdmin(tokenResult) {
  return tokenResult.valid && tokenResult.role === ADMIN_ROLE;
}

// Privilege escalation via role override in extra data
function getEffectiveRole(tokenResult) {
  if (!tokenResult.valid) return null;

  // Feature flag: if flags bit 0 is set, check extra data for role override
  if (tokenResult.flags & 0x01) {
    if (tokenResult.extraData && tokenResult.extraData.length >= 1) {
      return tokenResult.extraData.readUInt8(0);
    }
  }
  return tokenResult.role;
}

const sensitiveData = {
  secrets: ['API_KEY=sk-12345', 'DB_PASS=hunter2', 'ADMIN_TOKEN=xyz789'],
  users: Array.from(users.entries())
};

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);

  if (url.pathname === '/api/login' && req.method === 'POST') {
    let body = '';
    req.on('data', chunk => body += chunk);
    req.on('end', () => {
      try {
        const { userId } = JSON.parse(body);
        const user = users.get(userId);
        if (!user) {
          res.writeHead(401, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Unknown user' }));
          return;
        }
        const token = createToken(userId, user.role);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ token: token.toString('base64') }));
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Bad request' }));
      }
    });
  } else if (url.pathname === '/api/secrets' && req.method === 'GET') {
    const authHeader = req.headers['authorization'];
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'No token' }));
      return;
    }

    const tokenBuf = Buffer.from(authHeader.slice(7), 'base64');
    const tokenResult = parseToken(tokenBuf);

    if (!tokenResult.valid) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: tokenResult.error }));
      return;
    }

    const effectiveRole = getEffectiveRole(tokenResult);

    if (effectiveRole !== ADMIN_ROLE) {
      res.writeHead(403, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Admin only' }));
      return;
    }

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(sensitiveData));
  } else if (url.pathname === '/api/profile' && req.method === 'GET') {
    const authHeader = req.headers['authorization'];
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'No token' }));
      return;
    }

    const tokenBuf = Buffer.from(authHeader.slice(7), 'base64');
    const tokenResult = parseToken(tokenBuf);

    if (!tokenResult.valid) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: tokenResult.error }));
      return;
    }

    const user = users.get(tokenResult.userId);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ userId: tokenResult.userId, name: user?.name, role: tokenResult.role }));
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.listen(3000);
module.exports = { createToken, parseToken, getEffectiveRole, server };
